Q: Put a border around text inside a div A: <pre><code>.signup {
    border: 2px solid whitesmoke;
    border-radius: 6px;
    margin: 40px;
    padding: 10px;
}
</code></pre>
<pre><code>&lt;span class=&quot;signup&quot;&gt; Sign up&lt;/span&gt;
</code></pre>
<p>This worked for me. The trick seems to be the margin and padding together. I also used a span.</p>

Q: Could I to develop a dynamic popup of a JCombobox editable, that changes the content while the user insert or remove text? A: <p>It seems problem makes <code>comboBox.setModel(comb);</code> because it is executed inside <code>DocumentListener()</code> and &quot;changes in model&quot; may generate another event which will be run another <code>Listener</code> and it will try to run another <code>comboBox.setModel(comb);</code>, etc. - and it may create endless loop.</p>
<p>It may need to execute it later</p>
<pre><code>SwingUtilities.invokeLater(() -&gt; {
    comboBox.setModel(comb);
    comboBox.setPopupVisible(false);
});
</code></pre>
<hr />
<pre><code>            @Override
            public void insertUpdate(DocumentEvent e) {
                String src = editor.getText();
                String[] lista;
                System.out.println(&quot;el contenido es:&quot;+src);

                lista = FiltrarUsuarios(src);
                comb = new DefaultComboBoxModel&lt;String&gt;(lista); //usuarios
                SwingUtilities.invokeLater(() -&gt; {
                    comboBox.setModel(comb);
                    comboBox.setPopupVisible(false);
                });
            }

            @Override
            public void removeUpdate(DocumentEvent e) {

                String src = editor.getText();
                String[] lista;

                System.out.println(&quot;Ahora es borrar contenido. El contenido es:&quot;+src);
                if (src.equals(&quot;&quot;)) {
                    comb = new DefaultComboBoxModel&lt;String&gt;(usuarios);
                    SwingUtilities.invokeLater(() -&gt; {
                        comboBox.setModel(comb);
                        comboBox.setPopupVisible(false);
                    });
                } else {
                    lista = FiltrarUsuarios(src);
                    comb = new DefaultComboBoxModel&lt;String&gt;(lista); //usuarios
                    SwingUtilities.invokeLater(() -&gt; {
                        comboBox.setModel(comb);
                        comboBox.setPopupVisible(false);
                    });
                }
            }
</code></pre>

Q: Ideal language for fast binary feature minimization + any other general advice A: <pre><code># Optimal C++ Bitmask Implementation


#include &lt;bits/stdc++.h&gt;
using namespace std;

vector&lt;uint64_t&gt; rows;
int n_samples, n_packs; // f/64

// Precompute distinguishing masks for pairs
vector&lt;vector&lt;uint64_t&gt;&gt; pair_masks;

bool distinguishes(const uint64_t* feature_mask, int i, int j) {
  for(int k = 0; k &lt; n_packs; k++) {
    if ((rows[i][k] ^ rows[j][k]) &amp;amp; feature_mask[k]) return true;
  }
  return false;
}

bool valid_set(const vector&lt;int&gt;&amp;amp; features) {
  uint64_t mask[8] = {0}; // 512 bits max
  for(int f : features) mask[f/64] |= (1ULL &lt;&lt; (f%64));
  for(int i = 0; i &lt; n_samples; i++) for(int j = i+1; j &lt; n_samples; j++) {
    if(!distinguishes(mask, i, j)) return false;
  }
  return true;
}

int main() {

  cout &lt;&lt; &quot;Minimal distinguishing features: &quot; &lt;&lt; endl;
}

</code></pre>
